window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b9fcf3a2a51c61e3"]={"versions": [{"id": "FIG-b9fcf3a2a51c61e3", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm im Kontext der AUTOSAR Classic Platform (SWS CAN Network Management). Das Diagramm stellt das Softwaremodul <code>CanNm</code> mit seinen statischen Schnittstellenbeziehungen (bereitgestellte und angeforderte Schnittstellen) zu benachbarten BSW-Modulen (u. a. CanIf, Nm, PduR, Det) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität:</p>\n<ul class=\"fig-list\"><li><code>«module» CanNm</code>: BSW-Modul des CAN-Netzwerkmanagements.\n</li></ul>\n<p class=\"fig-p\">Bereitgestellte Schnittstellen (<code>«realize»</code>, durchgezogene Linien):</p>\n<ul class=\"fig-list\"><li><code>CanNm</code>: Modulschnittstelle.\n</li><li><code>CanNm_Transmit</code> (<code>«derived_generic_interface»</code>): Schnittstelle zum Anfordern von Übertragungen.\n</li><li><code>CanNm_Types</code>: Bereitgestellte Datentypspezifikationen des CAN-NM.\n</li></ul>\n<p class=\"fig-p\">Angeforderte Schnittstellen (gestrichelte Pfeile / Abhängigkeiten):</p>\n<ul class=\"fig-list\"><li><code>«derived_generic_interface» CanIf_Transmit</code> (<code>«optional»</code>): Schnittstelle zum CAN-Interface für das Senden.\n</li><li><code>«derived_generic_interface» PduR_CanNmTriggerTransmit</code> (<code>«optional»</code>): Trigger-Transmit-Aufruf an den PDU-Router.\n</li><li><code>Nm_NetworkStartIndication</code> (<code>«mandatory»</code>): Rückmeldung an das generische NM bei Netzstart.\n</li><li><code>«derived_generic_interface» PduR_CanNmTxConfirmation</code> (<code>«optional»</code>): Sende-Bestätigung an den PDU-Router.\n</li><li><code>Nm_PrepareBusSleepMode</code> (<code>«mandatory»</code>): Benachrichtigung des NM-Koordinators über die Vorbereitung des Bus-Sleep-Modus.\n</li><li><code>«derived_generic_interface» PduR_CanNmRxIndication</code> (<code>«optional»</code>): Empfangsindikation an den PDU-Router.\n</li><li><code>Nm_Types</code> (<code>«mandatory»</code>): Nutzung der allgemeinen Datentypen des generischen NM.\n</li><li><code>Nm_CarWakeUpIndication</code> (<code>«optional»</code>): Indikation eines Car-Wakeup-Signals an das generische NM.\n</li><li><code>Det_ReportError</code> (<code>«optional»</code>): Fehlermeldung an den Default Error Tracer.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert die statische Schnittstellenarchitektur ohne Sequenz- oder Zeitaspekte. Dynamisch interagiert <code>CanNm</code> über Aufrufe an das unterlagerte <code>CanIf</code> (<code>CanIf_Transmit</code>) sowie an übergeordnete Schichten wie das generische Netzwerkmanagement (<code>Nm</code>) zur Statussynchronisation (z. B. Netzwerkstart, Vorbereitung auf Bus-Sleep, Wake-Up). Für Nutzdaten bzw. Routingfunktionen tauscht <code>CanNm</code> PDUs über PduR-Schnittstellen (<code>RxIndication</code>, <code>TxConfirmation</code>, <code>TriggerTransmit</code>) aus. Laufzeitfehler werden an das <code>Det</code> gemeldet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektur- und Konfigurationsvorgaben:</p>\n<ul class=\"fig-list\"><li>Pflichtabhängigkeiten (<code>«mandatory»</code>) müssen in jeder Integration implementiert bzw. angebunden sein (<code>Nm_NetworkStartIndication</code>, <code>Nm_PrepareBusSleepMode</code>, <code>Nm_Types</code>).\n</li><li>Optionale Schnittstellen (<code>«optional»</code>) hängen von der Konfiguration und Feature-Aktivierung ab (z. B. Det-Reporting, PduR-Kopplung, Car-Wakeup-Unterstützung).\n</li><li><code>CanNm</code> implementiert generische Schnittstellenableitungen (<code>«derived_generic_interface»</code>), wodurch typspezifische PDU- und Übertragungsmechanismen standardisiert abgebildet werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-74ba4fa982d4a3c7", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm im Kontext der AUTOSAR Classic Platform (SWS CAN Network Management). Das Diagramm stellt das Softwaremodul <code>CanNm</code> mit seinen statischen Schnittstellenbeziehungen (bereitgestellte und angeforderte Schnittstellen) zu benachbarten BSW-Modulen (u. a. CanIf, Nm, PduR, Det) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität:</p>\n<ul class=\"fig-list\"><li><code>«module» CanNm</code>: BSW-Modul des CAN-Netzwerkmanagements.\n</li></ul>\n<p class=\"fig-p\">Bereitgestellte Schnittstellen (<code>«realize»</code>, durchgezogene Linien):</p>\n<ul class=\"fig-list\"><li><code>CanNm</code>: Modulschnittstelle.\n</li><li><code>CanNm_Transmit</code> (<code>«derived_generic_interface»</code>): Schnittstelle zum Anfordern von Übertragungen.\n</li><li><code>CanNm_Types</code>: Bereitgestellte Datentypspezifikationen des CAN-NM.\n</li></ul>\n<p class=\"fig-p\">Angeforderte Schnittstellen (gestrichelte Pfeile / Abhängigkeiten):</p>\n<ul class=\"fig-list\"><li><code>«derived_generic_interface» LSduR_CanNmTransmit</code> (<code>«optional»</code>): Schnittstelle zum Large SDU Router für das Senden.\n</li><li><code>«derived_generic_interface» PduR_CanNmTriggerTransmit</code> (<code>«optional»</code>): Trigger-Transmit-Aufruf an den PDU-Router.\n</li><li><code>Nm_NetworkStartIndication</code> (<code>«mandatory»</code>): Rückmeldung an das generische NM bei Netzstart.\n</li><li><code>«derived_generic_interface» PduR_CanNmTxConfirmation</code> (<code>«optional»</code>): Sende-Bestätigung an den PDU-Router.\n</li><li><code>Nm_PrepareBusSleepMode</code> (<code>«mandatory»</code>): Benachrichtigung des NM-Koordinators über die Vorbereitung des Bus-Sleep-Modus.\n</li><li><code>«derived_generic_interface» PduR_CanNmRxIndication</code> (<code>«optional»</code>): Empfangsindikation an den PDU-Router.\n</li><li><code>Nm_Types</code> (<code>«mandatory»</code>): Nutzung der allgemeinen Datentypen des generischen NM.\n</li><li><code>Nm_CarWakeUpIndication</code> (<code>«optional»</code>): Indikation eines Car-Wakeup-Signals an das generische NM.\n</li><li><code>Det_ReportError</code> (<code>«optional»</code>): Fehlermeldung an den Default Error Tracer.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert die statische Schnittstellenarchitektur ohne Sequenz- oder Zeitaspekte. Dynamisch interagiert <code>CanNm</code> über Aufrufe an den <code>LSduR</code> (<code>LSduR_CanNmTransmit</code>) sowie an übergeordnete Schichten wie das generische Netzwerkmanagement (<code>Nm</code>) zur Statussynchronisation (z. B. Netzwerkstart, Vorbereitung auf Bus-Sleep, Wake-Up). Für Nutzdaten bzw. Routingfunktionen tauscht <code>CanNm</code> PDUs über PduR-Schnittstellen (<code>RxIndication</code>, <code>TxConfirmation</code>, <code>TriggerTransmit</code>) aus. Laufzeitfehler werden an das <code>Det</code> gemeldet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektur- und Konfigurationsvorgaben:</p>\n<ul class=\"fig-list\"><li>Pflichtabhängigkeiten (<code>«mandatory»</code>) müssen in jeder Integration implementiert bzw. angebunden sein (<code>Nm_NetworkStartIndication</code>, <code>Nm_PrepareBusSleepMode</code>, <code>Nm_Types</code>).\n</li><li>Optionale Schnittstellen (<code>«optional»</code>) hängen von der Konfiguration und Feature-Aktivierung ab (z. B. Det-Reporting, PduR-Kopplung, Car-Wakeup-Unterstützung).\n</li><li><code>CanNm</code> implementiert generische Schnittstellenableitungen (<code>«derived_generic_interface»</code>), wodurch typspezifische PDU- und Übertragungsmechanismen standardisiert abgebildet werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-b9fcf3a2a51c61e3", "to": "FIG-74ba4fa982d4a3c7", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Die genutzte Schnittstelle für das Senden von NM-Botschaften wurde geändert: Die ausgehende optionale Abhängigkeit <code>«derived_generic_interface» CanIf_Transmit</code> wurde ersetzt durch <code>«derived_generic_interface» LSduR_CanNmTransmit</code>.\n</li></ul>"}]};
